fn is_letter(c: Str) -> Bool {
  return "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ".contains(c)
}

fn is_digit(c: Str) -> Bool {
  return "0123456789".contains(c)
}

fn is_space(c: Str) -> Bool {
  return c == " " or c == "\t" or c == "\n" or c == "\r"
}

pub fn tokens(src: Str) -> Result[List[Str], Str] {
  let cs = src.chars()
  let n = cs.len()
  var out: List[Str] = []
  var i = 0
  while i < n {
    let c = cs.get_or(i, "")
    let nxt = cs.get_or(i + 1, "")
    if is_space(c) {
      i = i + 1
    } else if is_letter(c) or c == "_" {
      var j = i + 1
      while j < n and (is_letter(cs.get_or(j, "")) or is_digit(cs.get_or(j, "")) or cs.get_or(j, "") == "_") {
        j = j + 1
      }
      out = out.push(cs.slice(i, j).join(""))
      i = j
    } else if is_digit(c) {
      var j = i + 1
      while j < n and is_digit(cs.get_or(j, "")) {
        j = j + 1
      }
      out = out.push(cs.slice(i, j).join(""))
      i = j
    } else if c == "\"" {
      var j = i + 1
      var closed = false
      while j < n and not closed {
        let d = cs.get_or(j, "")
        if d == "\\" {
          j = j + 2
        } else if d == "\"" {
          closed = true
        } else {
          j = j + 1
        }
      }
      if not closed {
        return Err("unterminated string")
      }
      out = out.push(cs.slice(i, j + 1).join(""))
      i = j + 1
    } else {
      let two = c + nxt
      if two == "==" or two == "!=" or two == "<=" or two == ">=" or two == "->" {
        out = out.push(two)
        i = i + 2
      } else if "+-*/<>=()\{\},;".contains(c) {
        out = out.push(c)
        i = i + 1
      } else {
        return Err("unexpected {c}")
      }
    }
  }
  return Ok(out)
}
